/*
 * Description: Functional React component that displays the current score, high score, and a button to reset the high score using cookies.
 * PreCondition: Requires score, highScore values, and a setHighScore function passed as props. `js-cookie` must be installed.
 * PostCondition: Displays score information and allows the user to clear the high score cookie and reset the state.
 */

import React from "react";
import Cookies from "js-cookie";
import './Board.css'; 

const ScorePanel = ({ score, highScore, setHighScore }) => (
  <div className="score-panel">
    <div className="score-item">Score: {score}</div>
    <div className="score-item">High Score: {highScore}</div>
    <button
      className="reset-button"
      onClick={() => {
        Cookies.remove("highScore");
        setHighScore(0);
      }}
    >
      Reset High Score
    </button>
  </div>
);

/*
 * Description: Exports the ScorePanel component for use in the game UI.
 * PreCondition: ScorePanel must be defined.
 * PostCondition: Component is available for import by parent components.
 */
export default ScorePanel;