/*
 * Description: Main game logic component for the sliding Match-3 game. Handles rendering, tile movement, scoring, effects, and game-over conditions.
 * PreCondition: Game environment must be initialized with helper modules (utils, Tile, Particles, etc.), and props include an onGameOver callback.
 * PostCondition: A functional board is rendered with drag-to-slide logic, match checking, move tracking, and animations.
 */
import React, { useEffect, useState, useRef } from "react";
import "./Board.css";
import Tile from "./Tile";
import ScorePanel from "./ScorePanel";
import Particles from "./Particles";
import ShuffleBanner from "./ShuffleBanner";
import Cookies from "js-cookie";
import MoveLimit from "../components/utils/MoveLimit.jsx";
import { createBoard, getMatches, handleMatches } from "../components/utils/BoardUtils.js";
import { width, cellSize } from "../components/utils/Constants.js";

/*
 * Description: Board component that manages game state, including board generation, dragging logic, score, and game over.
 * PreCondition: Must be rendered by a parent component with a valid onGameOver function.
 * PostCondition: Game logic, animations, and tile movements are processed and rendered.
 */
const Board = ({ onGameOver }) => {
  const [board, setBoard] = useState([]);
  const [dragging, setDragging] = useState(null);
  const [draggingIndex, setDraggingIndex] = useState(null);
  const [draggingAxis, setDraggingAxis] = useState(null);
  const [startBoard, setStartBoard] = useState(null);
  const [score, setScore] = useState(0);
  const [highScore, setHighScore] = useState(Number(Cookies.get("highScore") || 0));
  const [particles, setParticles] = useState([]);
  const [flashingTiles, setFlashingTiles] = useState(new Set());
  const [showShuffleBanner, setShowShuffleBanner] = useState(false);
  const [movesLeft, setMovesLeft] = useState(null); 
  const [initialMoves, setInitialMoves] = useState(null);

  const boardRef = useRef(null);
  const gameOverHandled = useRef(false);

   /*
   * Description: Initializes the board without any immediate matches.
   * PreCondition: Called at game start or restart.
   * PostCondition: Board is filled with tiles and set in state.
   */
  const initializeBoard = () => {
    let newBoard = createBoard();
    while (getMatches(newBoard).length > 0) {
      newBoard = createBoard();
    }
    setBoard(newBoard);
  };

    /*
   * Description: Sets up the initial board when component mounts.
   * PreCondition: Component must be mounted.
   * PostCondition: Board state is initialized.
   */
  useEffect(() => {
    initializeBoard();
  }, []);

  
  /*
   * Description: Updates high score in cookies if the score exceeds current high score.
   * PreCondition: Score must change.
   * PostCondition: Cookie is updated and high score state is synced.
   */
  useEffect(() => {
    if (score > highScore) {
      setHighScore(score);
      Cookies.set("highScore", score, { expires: 365 });
    }
  }, [score]);
  
  /*
   * Description: Ends the game when moves run out, triggering onGameOver.
   * PreCondition: movesLeft must reach 0 and initialMoves must be set.
   * PostCondition: Game over logic runs once.
   */
  useEffect(() => {
    if (movesLeft === 0 && initialMoves !== null && !gameOverHandled.current) {
      onGameOver(score, initialMoves); 
      gameOverHandled.current = true;
    }
  }, [movesLeft, score, onGameOver, initialMoves]);
  
  /*
   * Description: Starts the drag movement for a tile.
   * PreCondition: Mouse is pressed on a valid tile and moves remain.
   * PostCondition: Drag state is set and board snapshot is saved.
   */
  const startDrag = (e, index) => {
    e.preventDefault();
    e.stopPropagation();
    if (movesLeft <= 0) return;
    setDragging({ startX: e.clientX, startY: e.clientY });
    setStartBoard([...board]);
    setDraggingIndex(index);
    setDraggingAxis(null);
  };

  /*
   * Description: Handles live dragging movement and tile shifting.
   * PreCondition: User is dragging and a direction is established.
   * PostCondition: Tiles shift accordingly in a row or column.
   */
  const onDrag = (e) => {
    e.preventDefault();
    if (!dragging || draggingIndex == null) return;

    const dx = e.clientX - dragging.startX;
    const dy = e.clientY - dragging.startY;

    if (!draggingAxis) {
      if (Math.abs(dx) > Math.abs(dy)) {
        setDraggingAxis("x");
      } else {
        setDraggingAxis("y");
      }
      return;
    }

    const delta = draggingAxis === "x" ? Math.round(dx / cellSize) : Math.round(dy / cellSize);
    if (delta === 0) return;

    const newBoard = [...startBoard];

    if (draggingAxis === "x") {
      const row = Math.floor(draggingIndex / width);
      const col = draggingIndex % width;
      const newCol = Math.min(Math.max(col + delta, 0), width - 1);
      const start = row * width;
      const rowTiles = newBoard.slice(start, start + width);

      if (newCol > col) {
        const movingTile = rowTiles[col];
        for (let i = col; i < newCol; i++) {
          rowTiles[i] = rowTiles[i + 1];
        }
        rowTiles[newCol] = movingTile;
      } else if (newCol < col) {
        const movingTile = rowTiles[col];
        for (let i = col; i > newCol; i--) {
          rowTiles[i] = rowTiles[i - 1];
        }
        rowTiles[newCol] = movingTile;
      }

      for (let i = 0; i < width; i++) {
        newBoard[start + i] = rowTiles[i];
      }

    } else if (draggingAxis === "y") {
      const col = draggingIndex % width;
      const row = Math.floor(draggingIndex / width);
      const newRow = Math.min(Math.max(row + delta, 0), width - 1);
      const colTiles = [];

      for (let r = 0; r < width; r++) {
        colTiles.push(newBoard[r * width + col]);
      }

      if (newRow > row) {
        const movingTile = colTiles[row];
        for (let r = row; r < newRow; r++) {
          colTiles[r] = colTiles[r + 1];
        }
        colTiles[newRow] = movingTile;
      } else if (newRow < row) {
        const movingTile = colTiles[row];
        for (let r = row; r > newRow; r--) {
          colTiles[r] = colTiles[r - 1];
        }
        colTiles[newRow] = movingTile;
      }

      for (let r = 0; r < width; r++) {
        newBoard[r * width + col] = colTiles[r];
      }
    }

    setBoard(newBoard);
  };

   /*
   * Description: Ends the drag, checks for matches, and reverts if none found.
   * PreCondition: User releases mouse after dragging.
   * PostCondition: Board updates with match or reverts to start state.
   */
  const endDrag = (e) => {
    e.preventDefault();
    if (!startBoard) return;
    const matchCheck = getMatches(board);
    if (matchCheck.length > 0) {
      const newBoard = handleMatches(board, setScore, setParticles);
      setBoard(newBoard);
      setMovesLeft(prev => prev - 1);
    } else {
      setBoard(startBoard);
    }
    setDragging(null);
    setDraggingIndex(null);
    setDraggingAxis(null);
  };

   /*
   * Description: Resets the game with a new board and resets all scores/moves.
   * PreCondition: User triggers a restart (e.g., via MoveLimit component).
   * PostCondition: Game is restarted with a fresh board.
   */
  const restartGame = () => {
    initializeBoard();
    setScore(0);
    setMovesLeft(initialMoves);
    setHighScore(0);
    Cookies.remove("highScore");
    gameOverHandled.current = false;
  };

    /*
   * Description: Sets the starting number of moves based on user selection.
   * PreCondition: Called with a valid move count.
   * PostCondition: Game state is updated to begin play.
   */
  const selectMoveCount = (count) => {
    setInitialMoves(count);
    setMovesLeft(count);
  };

  /*
   * Description: Renders the move selection screen before the game starts.
   * PreCondition: initialMoves is null.
   * PostCondition: Allows the user to pick starting move count.
   */
  if (initialMoves === null) {
    return (
      <div className="move-select-screen">
        <h1>Select Number of Moves</h1>
        <div className="move-options">
          {[10, 20, 30, 40, 50].map(count => (
            <button key={count} onClick={() => selectMoveCount(count)}>
              {count} Moves
            </button>
          ))}
        </div>
      </div>
    );
  }

   /*
   * Description: Main rendering of the board, score panel, and all tile-based game logic.
   * PreCondition: Game is started and initialMoves are set.
   * PostCondition: Full game UI is shown with interactivity.
   */
  return (
    <div className="board-wrapper">
      <ScorePanel score={score} highScore={highScore} setHighScore={setHighScore} />
      <div className="board-content">
        <MoveLimit movesLeft={movesLeft} onRestart={restartGame} />
        <div
          ref={boardRef}
          className="board"
          onMouseMove={onDrag}
          onMouseUp={endDrag}
          onMouseDown={(e) => e.preventDefault()}
        >
          {showShuffleBanner && <ShuffleBanner />}
          {board.map((tile, i) => (
            <Tile
              key={tile?.id ?? i}
              index={i}
              width={width}
              tile={tile}
              selected={draggingIndex === i}
              flash={flashingTiles.has(i)}
              onMouseDown={(e) => startDrag(e, i)}
            />
          ))}
          <Particles particles={particles} width={width} setParticles={setParticles} />
        </div>
      </div>
    </div>
  );
};

/*
 * Description: Exports the Board component for use in the main App.
 * PreCondition: Board must be defined.
 * PostCondition: Component can be imported and rendered externally.
 */
export default Board;
