/*
 * Description: Functional React component that renders animated particles at matched tile positions.
 * PreCondition: Requires an array of particle objects (with id, index, and color), board width, and a function to update particles.
 * PostCondition: Particles are rendered on screen and automatically removed after their animation completes.
 */
import React from "react";

const Particles = ({ particles, width, setParticles }) => (
  <>
    {particles.map(({ id, index, color }) => {
      const x = (index % width) * 60 + 15;
      const y = Math.floor(index / width) * 60 + 15;
      return (
        <div
          key={id}
          className="particle"
          style={{
            backgroundColor: color,
            top: y,
            left: x,
          }}
          onAnimationEnd={() =>
            setParticles((prev) => prev.filter((p) => p.id !== id))
          }
        />
      );
    })}
  </>
);

/*
 * Description: Exports the Particles component for use in game animations.
 * PreCondition: Particles must be defined.
 * PostCondition: Component can be imported and used in other files like Board.
 */
export default Particles;