/*
 * Description: Utility functions for tile management, board creation, match detection, and score handling.
 * PreCondition: Constants such as `tileTypes` and `width` must be defined and imported.
 * PostCondition: Enables generation of new tiles, detection of matches, and board updates with scoring logic.
 */
import { tileTypes, width } from "./Constants.js";

/*
 * Description: Utility functions for tile management, board creation, match detection, and score handling.
 * PreCondition: Constants such as `tileTypes` and `width` must be defined and imported.
 * PostCondition: Enables generation of new tiles, detection of matches, and board updates with scoring logic.
 */
let idCounter = 0;

/*
 * Description: Returns a randomly selected tile with optional spawn flag.
 * PreCondition: tileTypes must be a non-empty array.
 * PostCondition: Tile object is returned with a unique ID and properties.
 */
export const getRandomTile = (justSpawned = false) => {
  const type = tileTypes[Math.floor(Math.random() * tileTypes.length)];
  return {
    id: idCounter++,
    justSpawned,
    ...type,
  };
};

/*
 * Description: Creates a new board with randomly spawned tiles.
 * PreCondition: Board width must be defined.
 * PostCondition: Returns a flat array representing the game board.
 */
export const createBoard = () =>
  Array.from({ length: width * width }, () => getRandomTile(true));

/*
 * Description: Detects all match groups of 3 or more identical tiles in a row or column.
 * PreCondition: Board must be a flat array of tile objects or nulls.
 * PostCondition: Returns an array of match objects with indices and types.
 */
export const getMatches = (board) => {
  const matches = [];

  const addMatch = (indices, type, name) => {
    matches.push({ indices, type, name });
  };

  for (let i = 0; i < width * width; i++) {
    const base = board[i];
    if (!base) continue;
    const name = base.name;

    for (let len = 5; len >= 3; len--) {
      if (i % width <= width - len) {
        const group = Array.from({ length: len }, (_, k) => i + k);
        if (group.every(idx => board[idx]?.name === name)) {
          addMatch(group, len, name);
        }
      }

      if (i < width * (width - len + 1)) {
        const group = Array.from({ length: len }, (_, k) => i + k * width);
        if (group.every(idx => board[idx]?.name === name)) {
          addMatch(group, len, name);
        }
      }

      if (
        i % width <= width - 3 &&
        i < width * (width - 2) &&
        board[i]?.name === name &&
        board[i + 1]?.name === name &&
        board[i + 2]?.name === name &&
        board[i + width]?.name === name &&
        board[i + width * 2]?.name === name
      ) {
        addMatch([i, i + 1, i + 2, i + width, i + width * 2], "T", name);
      }
    }
  }

  return matches;
};


/*
 * Description: Applies match results to the board, updates score, spawns particles, and refills tiles.
 * PreCondition: `inputBoard` must be a valid board, `setScore` and `setParticles` are state update functions.
 * PostCondition: Returns a new board with matches removed, points awarded, and new tiles generated.
 */
export const handleMatches = (inputBoard, setScore, setParticles) => {
  let newBoard = [...inputBoard];
  let matches;

  do {
    matches = getMatches(newBoard);
    if (matches.length === 0) break;

    const matchedIndices = new Set();
    const newParticles = [];

    matches.forEach(({ indices, type, name }) => {
      indices.forEach(idx => matchedIndices.add(idx));
      indices.forEach(idx => {
        newParticles.push({
          id: `p-${idx}-${Date.now()}`,
          index: idx,
          color: tileTypes.find(t => t.name === name).color,
        });
      });

      const points =
        type === "T" || type === "L"
          ? 150
          : type === 5
          ? 100
          : type === 4
          ? 60
          : 30;
      setScore(prev => prev + points);
    });

    setParticles(prev => [...prev, ...newParticles]);

    matchedIndices.forEach(idx => {
      newBoard[idx] = null;
    });

    for (let col = 0; col < width; col++) {
      const column = [];
      for (let row = width - 1; row >= 0; row--) {
        const idx = row * width + col;
        if (newBoard[idx] !== null) {
          column.push(newBoard[idx]);
        }
      }

      while (column.length < width) {
        column.push(getRandomTile(true));
      }

      for (let row = width - 1; row >= 0; row--) {
        const idx = row * width + col;
        newBoard[idx] = column[width - 1 - row];
      }
    }
  } while (matches.length > 0);

  return newBoard;
};