import React, { useState, useMemo } from "react";
import Board from "./components/Board";
import "./App.css";


/*
 * Description: Defines the main App component which handles rendering the UI and tracking the game history.
 * PreCondition: App is mounted in a valid HTML container with proper DOM structure.
 * PostCondition: App is rendered with Board component and game history management.
 */
function App() {

  /*
   * Description: Initializes state for storing previous games, filtering type, and search query.
   * PreCondition: Component is mounted.
   * PostCondition: State variables are available to track user interactions and game outcomes.
   */
  const [gameHistory, setGameHistory] = useState([]);
  const [filterType, setFilterType] = useState("score"); 
  const [searchQuery, setSearchQuery] = useState("");

  /*
   * Description: Callback invoked when a game ends. Stores the result in game history with a downloadable link.
   * PreCondition: Game is over and score/move count are available.
   * PostCondition: Game history state is updated and a downloadable score file is created.
   */
  const handleGameOver = (finalScore, moveCount) => {
    const now = new Date();
    const timestamp = now.toLocaleString();
    const content = `Score: ${finalScore}\nMoves Selected: ${moveCount}\nDate: ${timestamp}`;
    const blob = new Blob([content], { type: "text/plain" });
    const url = URL.createObjectURL(blob);

    setGameHistory(prev => [
      { score: finalScore, moveCount, timestamp, url, dateObj: new Date() },
      ...prev
    ]);
  };

  
  /*
   * Description: Computes a filtered and sorted list of previous games based on selected filter and search query.
   * PreCondition: gameHistory, filterType, and searchQuery must be defined.
   * PostCondition: Returns a filtered/sorted array of past game sessions to be displayed in the UI.
   */
  const filteredAndSortedGames = useMemo(() => {
    let sorted = [...gameHistory];

    if (filterType === "score") {
      sorted.sort((a, b) => b.score - a.score);
    } else if (filterType === "moves") {
      sorted.sort((a, b) => b.moveCount - a.moveCount); 
    } else if (filterType === "date") {
      sorted.sort((a, b) => b.dateObj - a.dateObj);
    }

    const query = searchQuery.toLowerCase();
    return sorted.filter((game) => {
      if (filterType === "score") {
        return game.score.toString().includes(query);
      } else if (filterType === "moves") {
        return game.moveCount.toString().includes(query);
      } else if (filterType === "date") {
        return game.timestamp.toLowerCase().includes(query);
      }
      return true;
    });
  }, [gameHistory, filterType, searchQuery]);


  /*
   * Description: Renders the game UI including the title, search/filter controls, previous games, and the Board component.
   * PreCondition: ReactDOM must render this App component inside a valid container.
   * PostCondition: Complete game interface is rendered in the browser.
   */
  return (
    <div className="App">
      <div className="game-title-container">
        <h1 className="game-title">GEMS</h1>
        <p className="game-subtitle">Made in React by Cole Cummings</p>

        <div className="game-history-container">
          <h3>Previous Games:</h3>

          <div className="search-controls">
            <select
              value={filterType}
              onChange={(e) => setFilterType(e.target.value)}
            >
              <option value="score">Filter by Score</option>
              <option value="moves">Filter by Moves</option>
              <option value="date">Filter by Date</option>
            </select>
            <input
              type="text"
              placeholder={`Search by ${filterType}`}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>

          <div className="game-history-scroll">
            {filteredAndSortedGames.length === 0 && <p>No games found.</p>}
            <ul>
              {filteredAndSortedGames.map((game, index) => (
                <li key={index}>
                  {game.timestamp} — {game.score} points ({game.moveCount} moves)
                  <a href={game.url} download={`highscore_${index + 1}.txt`}>
                    <button style={{ marginLeft: '10px' }}>Download</button>
                  </a>
                </li>
              ))}
            </ul>
          </div>
        </div>
      </div>

      <div className="game-container">
        <Board onGameOver={handleGameOver} />
      </div>
    </div>
  );
}

/*
 * Description: Exports the App component so it can be imported and rendered elsewhere in the project.
 * PreCondition: App must be defined as a function.
 * PostCondition: App becomes available to other modules via import.
 */
export default App;
