import React from "react";
import { motion } from "framer-motion";
import "./Tile.css";

/*
 * Description: Pixel dimension of each tile cell on the board.
 * PreCondition: Constant used for positioning calculations.
 * PostCondition: Used to compute tile layout positions.
 */
const cellSize = 60;

/*
 * Description: Functional component that renders a single animated tile on the board.
 * PreCondition: Props must include valid tile data and board width.
 * PostCondition: Tile is rendered at its appropriate location and animated using Framer Motion.
 */
const Tile = ({ index, width, tile, selected, flash, onMouseDown }) => {
  if (!tile) return null;

  const col = index % width;
  const row = Math.floor(index / width);

  const x = col * cellSize;
  const y = row * cellSize;
  const spawnY = -cellSize * (row + 2);

  return (
    <motion.div
      className={`tile ${selected ? "selected" : ""} ${flash ? "flash" : ""}`}
      style={{ touchAction: "none" }} 
      layoutId={String(tile.id)}
      initial={tile.justSpawned ? { x, y: spawnY } : false}
      animate={{ x, y }}
      transition={{
        type: "spring",
        damping: 15,
        stiffness: 200,
      }}
      onMouseDown={onMouseDown} 
    >
      <img
        src={tile.img}
        alt={tile.name}
        className="tile-img"
        draggable={false} 
      />
    </motion.div>
  );
};

/*
 * Description: Exports the Tile component for use in other modules like Board.
 * PreCondition: Tile must be defined.
 * PostCondition: Tile can be imported and used elsewhere.
 */
export default Tile;
