import React from 'react';
import ReactDOM from 'react-dom/client';
import './index.css';
import App from './App';

/*
 * Description: Entry point for the React application. Renders the root component (`App`) into the DOM.
 * PreCondition: An HTML element with the ID 'root' must exist in the HTML file. App component and required styles must be properly imported.
 * PostCondition: The React app is mounted and visible in the browser inside the 'root' element.
 */

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

