/*
 * Description: Functional component to display remaining moves or game over screen with restart option.
 * PreCondition: Requires `movesLeft` as a number and `onRestart` as a function.
 * PostCondition: Displays move counter when moves remain or a game over screen with restart when they reach zero.
 */
import React from "react";
import "./MoveLimit.css";

const MoveLimit = ({ movesLeft, onRestart }) => {
  if (movesLeft > 0) {
    return (
      <div className="move-limit">
        <p>Moves Left: {movesLeft}</p>
      </div>
    );
  }

  return (
    <div className="splash-screen">
      <h1>Game Over!</h1>
      <p>Game Over!</p>
      <button onClick={onRestart}>Restart Game</button>
    </div>
  );
};

/*
 * Description: Exports the MoveLimit component for usage in the board layout.
 * PreCondition: MoveLimit must be defined.
 * PostCondition: Can be imported and rendered by other components (e.g., Board).
 */
export default MoveLimit;
